/**
 * Entity-agnostic helpers for CatalogFacet.renderEntry implementations.
 * Engine render.ts only dispatches; dialect lives on facets / deferred meta.
 */
const RESERVED_IDENT = new Set([
    "break", "case", "catch", "class", "const", "continue", "debugger", "default",
    "delete", "do", "else", "export", "extends", "false", "finally", "for",
    "function", "if", "import", "in", "instanceof", "new", "null", "return",
    "super", "switch", "this", "throw", "true", "try", "typeof", "var", "void",
    "while", "with", "let", "static", "yield", "enum",
]);
/** Quote bag keys that are not safe bare identifiers. */
export function safeCatalogKey(name) {
    if (!/^[A-Za-z_$][A-Za-z0-9_$]*$/.test(name) || RESERVED_IDENT.has(name)) {
        return JSON.stringify(name);
    }
    return name;
}
/** `key: factoryName(),` — agent/skill/empty automation style. */
export function bareFactoryEntry(factoryName, keyName, baseIndent) {
    return {
        lines: [`${baseIndent}${safeCatalogKey(keyName)}: ${factoryName}(),`],
    };
}
/** `key: factoryName({ name, … }),` */
export function namedFactoryEntry(opts) {
    const parts = [`name: ${JSON.stringify(opts.name)}`];
    if (opts.parent !== undefined) {
        parts.push(`parent: ${JSON.stringify(opts.parent)}`);
    }
    if (opts.extraParts !== undefined)
        parts.push(...opts.extraParts);
    return {
        lines: [
            `${opts.baseIndent}${safeCatalogKey(opts.keyName)}: ${opts.factoryName}({ ${parts.join(", ")} }),`,
        ],
        extraFactories: opts.extraFactories,
    };
}
/** Narrow an unknown catalog ref to a name-bearing record. */
export function asNamedRef(ref) {
    if (ref === null || typeof ref !== "object") {
        throw new Error("catalog renderEntry expected an object ref");
    }
    const r = ref;
    if (typeof r.name !== "string") {
        throw new Error("catalog renderEntry expected ref.name: string");
    }
    return {
        name: r.name,
        parent: typeof r.parent === "string" ? r.parent : undefined,
        refName: typeof r.refName === "string" ? r.refName : undefined,
    };
}
/** `{ name }` only — org identity bags and similar. */
export function namedOnlyFactoryEntry(factoryName) {
    return (args) => {
        const named = asNamedRef(args.ref);
        return namedFactoryEntry({
            factoryName,
            keyName: args.keyName,
            baseIndent: args.baseIndent,
            name: named.name,
        });
    };
}
/**
 * `{ name }` with parent omitted — appCatalog injects parent from the root
 * (search tables).
 */
export function rootParentFactoryEntry(factoryName, extraParts) {
    return (args) => {
        const named = asNamedRef(args.ref);
        return namedFactoryEntry({
            factoryName,
            keyName: args.keyName,
            baseIndent: args.baseIndent,
            name: named.name,
            extraParts: extraParts?.(args.ref),
        });
    };
}
